namespace u=penta::algebra::universal;
namespace {
int checks=0,failures=0;
void expect(bool result,const char* message){++checks;if(!result){++failures;std::cerr<<"FAIL: "<<message<<'\n';}}
bool near(const u::Element& a,const u::Element& b,double tolerance=1e-11){if(a.coefficients().size()!=b.coefficients().size())return false;for(std::size_t i=0;i<a.coefficients().size();++i)if(std::abs(a.coefficients()[i]-b.coefficients()[i])>tolerance*(1+std::abs(b.coefficients()[i])))return false;return true;}
template<class F>void reject(F action,const char* message){bool rejected=false;try{action();}catch(const u::Error&){rejected=true;}expect(rejected,message);}
u::Element tableReference(const u::Element& a,const u::Element& b){std::vector<long double> sum(a.coefficients().size(),0);for(const auto& t:a.definition()->terms())sum[t.output]+=static_cast<long double>(a.coefficients()[t.left])*b.coefficients()[t.right]*t.coefficient;std::vector<double> value(sum.size());for(std::size_t k=0;k<sum.size();++k)value[k]=static_cast<double>(sum[k]);return u::Element(a.definition(),std::move(value));}
void builtins(){
    std::mt19937 random(8675309);std::uniform_real_distribution<double> sample(-1,1);
    const std::vector<std::pair<const char*,std::size_t>> names{{"real",1},{"complex",2},{"quaternion",4},{"octonion",8},{"sedenion",16},{"dual",2},{"dual_quaternion",8},{"split_complex",2},{"split_quaternion",4}};
    for(const auto& [name,n]:names){const auto def=u::builtin(name);expect(def->dimension()==n,"Builtin has the documented real dimension.");expect(def->properties().unital.value,"Every selected builtin declares its checked unit.");const auto one=u::Element::scalar(def,1);for(unsigned run=0;run<12;++run){std::vector<double> x(n),y(n);for(auto& value:x)value=sample(random);for(auto& value:y)value=sample(random);u::Element a(def,x),b(def,y);expect(near(u::multiply(one,a),a)&&near(u::multiply(a,one),a),"Native builtin unit acts on both sides.");expect(near(u::multiply(a,b),tableReference(a,b)),"Specialized native product agrees with the exported structure constants.");expect(near(u::conjugate(u::multiply(a,b)),u::multiply(u::conjugate(b),u::conjugate(a))),"Builtin conjugation reverses the product.");expect(near(u::conjugate(u::conjugate(a)),a),"Builtin conjugation is involutive.");expect(std::abs(u::metricNormSquared(a)-u::coordinateNorm(a)*u::coordinateNorm(a))<1e-11,"Explicit Euclidean coefficient metric is distinct from composition claims.");}}
    const auto h=u::builtin("quaternion");const auto i=u::Element::basis(h,1),j=u::Element::basis(h,2),k=u::Element::basis(h,3);expect(near(u::multiply(i,j),k)&&near(u::multiply(j,i),u::scale(k,-1)),"Hamilton i*j=k,j*i=-k.");expect(near(u::multiply(i,i),u::Element::scalar(h,-1)),"Hamilton imaginary square is-1.");expect(h->properties().associative.value&&h->properties().division.value,"Quaternion builtin has the known associative/division capabilities.");
    const auto o=u::builtin("octonion");bool nonassoc=false;for(std::size_t a=1;a<8&&!nonassoc;++a)for(std::size_t b=1;b<8&&!nonassoc;++b)for(std::size_t c=1;c<8&&!nonassoc;++c)nonassoc=u::coordinateNorm(u::associator(u::Element::basis(o,a),u::Element::basis(o,b),u::Element::basis(o,c)))>0;expect(nonassoc&&!o->properties().associative.value&&o->properties().alternative.value,"Octonion product is nonassociative and alternative.");
    const auto s=u::builtin("sedenion");bool zeroDivisor=false;u::Element divisor=u::Element::basis(s,1),partner=divisor;for(std::size_t a=1;a<16&&!zeroDivisor;++a)for(std::size_t b=a+1;b<16&&!zeroDivisor;++b)for(std::size_t c=1;c<16&&!zeroDivisor;++c)for(std::size_t d=c+1;d<16&&!zeroDivisor;++d)for(const double sign:{-1.,1.}){auto x=u::add(u::Element::basis(s,a),u::Element::basis(s,b));auto y=u::add(u::Element::basis(s,c),u::scale(u::Element::basis(s,d),sign));if(u::coordinateNorm(u::multiply(x,y))==0){zeroDivisor=true;divisor=x;partner=y;break;}}
    expect(zeroDivisor&&!s->properties().division.value&&!s->properties().alternative.value,"Sedenion construction has a nonzero zero-divisor pair and is not alternative/division.");if(zeroDivisor){const auto reciprocal=u::inverse(divisor);expect(near(u::multiply(divisor,reciprocal),u::Element::scalar(s,1))&&near(u::multiply(reciprocal,divisor),u::Element::scalar(s,1)),"Sedenion zero divisors still have canonical two-sided reciprocals.");const auto equation=u::solveLeft(divisor,u::multiply(divisor,partner));expect(equation.status==u::SolveStatus::SingularConsistent&&!equation.solution&&equation.rank<16,"Zero-divisor equation has singular operator and is not falsely unique.");}
    const auto goldenA=u::add(u::Element::basis(s,1),u::Element::basis(s,10)),goldenB=u::add(u::Element::basis(s,4),u::Element::basis(s,15));expect(u::coordinateNorm(u::multiply(goldenA,goldenB))==0,"Independent convention-specific golden pair(e1+e10)*(e4+e15)=0.");
    expect(near(u::associator(u::Element::basis(o,1),u::Element::basis(o,3),u::Element::basis(o,4)),u::scale(u::Element::basis(o,6),2)),"Independent octonion golden associator(e1,e3,e4)=2e6.");
    const auto dual=u::builtin("dual");const auto epsilon=u::Element::basis(dual,1);expect(u::coordinateNorm(u::multiply(epsilon,epsilon))==0,"Dual epsilon squared is zero.");reject([&]{(void)u::inverse(epsilon);},"Nilpotent dual epsilon has no reciprocal.");const auto x=u::Element(dual,{2,3});expect(near(u::inverse(x),u::Element(dual,{.5,-.75})),"Dual-number reciprocal uses real-part invertibility.");
    const auto split=u::builtin("split_complex");reject([&]{(void)u::inverse(u::Element(split,{1,1}));},"Split-complex zero divisors reject inversion.");const auto sq=u::builtin("split_quaternion");expect(near(u::multiply(u::Element::basis(sq,1),u::Element::basis(sq,1)),u::Element::scalar(sq,-1)),"Split quaternion i squared is-1.");expect(near(u::multiply(u::Element::basis(sq,2),u::Element::basis(sq,2)),u::Element::scalar(sq,1)),"Split quaternion j squared is+1.");
    for(unsigned p=0;p<=4;++p)for(unsigned q=0;q<=4-p;++q){const auto cl=u::builtin("clifford",{p,q});expect(cl->dimension()==(std::size_t(1)<<(p+q)),"Clifford dimension is2^(p+q).");for(unsigned bit=0;bit<p+q;++bit){const auto e=u::Element::basis(cl,std::size_t(1)<<bit);expect(near(u::multiply(e,e),u::Element::scalar(cl,bit<p?1:-1)),"Clifford generator square matches the declared signature.");}for(unsigned run=0;run<3;++run){std::vector<double> a(cl->dimension()),b(a.size()),c(a.size());for(auto& v:a)v=sample(random);for(auto& v:b)v=sample(random);for(auto& v:c)v=sample(random);expect(u::coordinateNorm(u::associator(u::Element(cl,a),u::Element(cl,b),u::Element(cl,c)))<1e-10,"Clifford multiplication is associative.");}}
    reject([&]{(void)u::builtin("clifford",{7,0});},"Unbounded Clifford dimension rejects.");reject([&]{(void)u::add(i,u::Element::basis(o,1));},"Different algebra definitions never mix implicitly.");
    const auto matrix=u::builtin("matrix2");expect(near(u::Element::scalar(matrix,1),u::Element(matrix,{1,0,0,1})),"M2R unit is E11+E22, not the first basis vector.");u::Element m(matrix,{1,2,3,4}),nn(matrix,{2,3,5,7});expect(near(u::multiply(m,nn),u::Element(matrix,{12,17,26,37})),"Native M2R multiplication agrees with ordinary matrix multiplication.");const auto matrixImported=u::fromJson(matrix->json());expect(matrixImported->properties().unital.value&&matrixImported->properties().associative.value&&!matrixImported->properties().division.value,"Imported M2R verifies composite unit and matrix identities.");
    const auto lie=u::builtin("lie_so3");u::Element lx(lie,{1,2,3}),ly(lie,{4,2,-1}),lz(lie,{-.5,2,1});const auto jacobi=u::add(u::add(u::multiply(lx,u::multiply(ly,lz)),u::multiply(ly,u::multiply(lz,lx))),u::multiply(lz,u::multiply(lx,ly)));expect(u::coordinateNorm(jacobi)<1e-12,"so3 cross-product preset satisfies Jacobi.");expect(!lie->properties().unital.value&&lie->unit().empty(),"so3 is explicitly nonunital.");reject([&]{(void)u::Element::scalar(lie,1);},"Nonunital Lie preset rejects automatic real scalar embedding.");
    const auto jordan=u::builtin("jordan_sym2");u::Element ja(jordan,{1,2,3}),jb(jordan,{2,-1,4});expect(near(u::multiply(ja,jb),u::multiply(jb,ja)),"Symmetric2x2 Jordan product is commutative.");expect(near(u::multiply(u::Element::scalar(jordan,1),ja),ja),"Jordan unit is E11+E22.");expect(u::coordinateNorm(u::associator(u::Element::basis(jordan,0),u::Element::basis(jordan,1),u::Element::basis(jordan,1)))>0,"Symmetric Jordan product is nonassociative.");expect(near(u::multiply(u::multiply(ja,ja),u::multiply(ja,ja)),u::power(ja,4)),"Special Jordan fourth powers are power-associative.");expect(std::abs(u::metricNormSquared(ja)-18)<1e-12,"Jordan metric is explicit symmetric-matrix Frobenius form.");expect(near(u::multiply(ja,u::inverse(ja)),u::Element::scalar(jordan,1)),"Jordan reciprocal is separately verified without assuming unique Jordan division.");
}
void importer(){
    using Json=nlohmann::json;
    expect(u::detail::sha256("")=="e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","Canonical identity uses standard SHA256 empty-vector digest.");expect(u::detail::sha256("abc")=="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad","Canonical identity uses standard SHA256 abc-vector digest.");
    const std::string dual=R"({"format":"StudioAlgebraDefinition","version":1,"name":"ImportedDual","dimension":2,"basis":["one","eps"],"coefficient_domain":"rational","unit":["1","0"],"omitted_products":"zero","products":[{"left":0,"right":0,"terms":[[0,"1"]]},{"left":0,"right":1,"terms":[[1,"1"]]},{"left":1,"right":0,"terms":[[1,"1"]]}]})";
    const auto d=u::fromJson(dual);expect(d->dimension()==2&&d->builtinKind().empty(),"User multiplication table imports as an immutable generic definition.");expect(d->properties().unital.value&&d->properties().unital.evidence==u::Evidence::ProvedExact,"Imported rational unit is verified exactly.");expect(d->properties().associative.value&&d->properties().associative.evidence==u::Evidence::ProvedExact,"Imported rational associativity is verified exactly.");expect(!d->properties().division.value&&d->properties().division.evidence==u::Evidence::Failed,"Nilpotent basis vector is an exact zero-divisor witness.");const auto eps=u::Element::basis(d,1);expect(u::coordinateNorm(u::multiply(eps,eps))==0,"Imported omitted-zero policy supplies epsilon squared zero.");const auto copy=u::fromJson(d->json());expect(copy->hash()==d->hash()&&copy->sourceHash()!=d->sourceHash(),"Canonical semantic hash ignores source formatting while source hash records exact bytes.");
    auto source=Json::parse(dual);source["unit"]={"0","1"};reject([&]{(void)u::fromJson(source.dump());},"A false unit vector rejects before scalar embedding.");source=Json::parse(dual);source["builtinKind"]="quaternion";reject([&]{(void)u::fromJson(source.dump());},"Untrusted JSON cannot spoof a specialized builtin kind.");source=Json::parse(dual);source["products"].push_back(source["products"][0]);reject([&]{(void)u::fromJson(source.dump());},"Duplicate ordered products reject.");source=Json::parse(dual);source["products"][0]["terms"].push_back({0,"1"});reject([&]{(void)u::fromJson(source.dump());},"Duplicate output coefficients reject rather than silently combine.");source=Json::parse(dual);source["basis"]={"one","one"};reject([&]{(void)u::fromJson(source.dump());},"Duplicate basis names reject.");source=Json::parse(dual);source["omitted_products"]="error";reject([&]{(void)u::fromJson(source.dump());},"Explicit complete-product policy catches missing products.");source=Json::parse(dual);source["products"][0]["terms"][0][1]="1/0";reject([&]{(void)u::fromJson(source.dump());},"Zero rational denominator rejects.");source=Json::parse(dual);source["products"][0]["terms"][0][1]="system(1)";reject([&]{(void)u::fromJson(source.dump());},"Coefficient strings are never executable expressions.");
    reject([&]{(void)u::fromJson("{\"format\":\"a\",\"format\":\"StudioAlgebraDefinition\"}");},"Duplicate JSON object keys reject.");
    const auto h=u::builtin("quaternion");auto exported=Json::parse(h->json());exported["name"]="CounterfeitQuaternion";exported["products"][0]["terms"][0][1]="2";reject([&]{(void)u::fromJson(exported.dump());},"Modified trusted-looking quaternion table still undergoes actual unit validation.");
    const auto importedH=u::fromJson(h->json());expect(importedH->hash()==h->hash()&&importedH->builtinKind().empty(),"Canonical builtin table can roundtrip without trusted fastpath privileges.");
    auto floating=Json::parse(dual);floating["coefficient_domain"]="floating";floating["unit"]={1.,0.};for(auto& product:floating["products"])for(auto& term:product["terms"])term[1]=1.;const auto approximate=u::fromJson(floating.dump());expect(approximate->properties().associative.evidence==u::Evidence::NumericalEvidence,"Approximate table identity checks never claim exact proof.");
    u::ImportOptions limited;limited.maxIdentityOperations=0;const auto unchecked=u::fromJson(dual,limited);expect(unchecked->properties().unital.value&&unchecked->properties().associative.evidence==u::Evidence::Unknown,"Zero optional proof budget preserves sound unit checks and reports unknown identities.");limited.cancellation=std::make_shared<std::atomic_bool>(true);reject([&]{(void)u::fromJson(dual,limited);},"Cancelled importer stops cooperatively.");
    auto nonunital=Json::parse(dual);nonunital["unit"]=nullptr;const auto nu=u::fromJson(nonunital.dump());reject([&]{(void)u::Element::scalar(nu,1);},"Nonunital definitions reject real-unit embedding.");
    auto nonassoc=Json::parse(u::builtin("sedenion")->json());const auto ns=u::fromJson(nonassoc.dump());expect(ns->properties().associative.evidence==u::Evidence::Failed&&ns->properties().alternative.evidence==u::Evidence::Failed,"Imported sedenion table fails complete polarized associativity/alternativity checks.");
}
void elementary(){
    const auto h=u::builtin("quaternion");const u::Element q(h,{.3,.4,0,0});const std::complex<double> z(.3,.4);
    const auto compare=[&](const u::Element& actual,std::complex<double> expected,const char* label){expect(near(actual,u::Element(h,{expected.real(),expected.imag(),0,0})),label);};
    compare(u::sine(q),std::sin(z),"Quaternion sine agrees with an independent complex slice.");compare(u::cosine(q),std::cos(z),"Quaternion cosine agrees with an independent complex slice.");compare(u::exponential(q),std::exp(z),"Quaternion exponential agrees with an independent complex slice.");compare(u::hyperbolicSine(q),std::sinh(z),"Quaternion sinh agrees with an independent complex slice.");compare(u::hyperbolicCosine(q),std::cosh(z),"Quaternion cosh agrees with an independent complex slice.");
    const auto d=u::builtin("dual");expect(near(u::exponential(u::Element(d,{.2,.7})),u::Element(d,{std::exp(.2),.7*std::exp(.2)})),"Dual exponential gives its exact nilpotent derivative term.");
    const auto split=u::builtin("split_complex");expect(near(u::exponential(u::Element(split,{.3,.4})),u::Element(split,{std::exp(.3)*std::cosh(.4),std::exp(.3)*std::sinh(.4)})),"Split-complex exponential uses the hyperbolic quadratic identity.");
    for(const double radius:{1.01,20.,20000.})for(const double shift:{0.,-1.})for(const double sign:{-1.,1.}){
        const auto plus=std::exp(shift)/2,minus=std::exp(shift-2*radius)/2;
        expect(near(u::exponential(u::Element(split,{-radius+shift,sign*radius})),u::Element(split,{plus+minus,sign*(plus-minus)})),"Split exponential preserves finite idempotent branches without overflowing separate factors.");
    }
    const auto splitQuaternion=u::builtin("split_quaternion");
    expect(near(u::exponential(u::Element(splitQuaternion,{-20000,0,20000,0})),u::Element(splitQuaternion,{.5,0,.5,0})),"Split-quaternion exponential retains a finite saturated hyperbolic slice.");
    for(const double divisor:{1e-309,std::numeric_limits<double>::denorm_min(),-1e-309})
        expect(near(u::divideByReal(u::Element(h,{divisor,-divisor,0,0}),divisor),u::Element(h,{1,-1,0,0})),"Real scalar division avoids reciprocal overflow for subnormal finite divisors.");
    reject([&]{(void)u::divideByReal(q,0);},"Zero real divisors still reject.");
    reject([&]{(void)u::divideByReal(q,std::numeric_limits<double>::infinity());},"Nonfinite real divisors still reject.");
    const auto sed=u::builtin("sedenion");expect(near(u::exponential(u::scale(u::Element::basis(sed,10),.4)),u::add(u::Element::scalar(sed,std::cos(.4)),u::scale(u::Element::basis(sed,10),std::sin(.4)))),"Sedenion one-element exponential preserves its quadratic calculus despite zero divisors.");
    const auto matrix=u::builtin("matrix2");const u::Element upper(matrix,{.3,.7,0,.3});expect(near(u::exponential(upper),u::Element(matrix,{std::exp(.3),.7*std::exp(.3),0,std::exp(.3)})),"General associative exponential handles a Jordan block and composite unit.");
    const auto tiny=u::exponential(u::Element(matrix,{0,1e-300,0,0}));expect(tiny.coefficients()[0]==1&&tiny.coefficients()[1]==1e-300&&tiny.coefficients()[3]==1,"Tiny nilpotent coordinates survive negligible intermediate Taylor terms.");
    const auto imported=u::fromJson(matrix->json());expect(near(u::sine(u::Element(imported,{.3,.7,0,.3})),u::Element(imported,{std::sin(.3),.7*std::cos(.3),0,std::sin(.3)})),"Imported exact associative table supports a whole-element sine.");
    const auto jordan=u::builtin("jordan_sym2");expect(near(u::exponential(u::Element(jordan,{0,.4,0})),u::Element(jordan,{std::cosh(.4),std::sinh(.4),std::cosh(.4)})),"Certified Jordan one-element exponential is evaluated in its generated associative subalgebra.");
    const auto cl=u::builtin("clifford",{1,1});const auto c=u::add(u::scale(u::Element::basis(cl,1),.3),u::scale(u::Element::basis(cl,2),.4));const auto norm=std::sqrt(.07);expect(near(u::exponential(c),u::add(u::Element::scalar(cl,std::cos(norm)),u::scale(c,std::sin(norm)/norm))),"Clifford scaled-series exponential agrees with its particular quadratic element.");
    const auto dq=u::builtin("dual_quaternion");expect(near(u::exponential(u::Element(dq,{0,0,0,0,0,.2,.3,.4})),u::Element(dq,{1,0,0,0,0,.2,.3,.4})),"Dual-quaternion nilpotent exponential retains every dual coordinate.");
    reject([&]{(void)u::exponential(u::Element::basis(u::builtin("lie_so3"),0));},"Nonunital Lie brackets do not silently acquire an exponential unit.");
    u::ImportOptions noProof;noProof.maxIdentityOperations=0;const auto uncertified=u::fromJson(matrix->json(),noProof);reject([&]{(void)u::exponential(u::Element::basis(uncertified,0));},"Unproved imported associativity does not enable scaling identities.");
    reject([&]{(void)u::exponential(u::Element(matrix,{1e100,0,0,1e100}));},"General function work bounds reject enormous unsupported scaling.");
}
void solve(){const auto h=u::builtin("quaternion");const u::Element a(h,{2,1,-.2,.4}),x(h,{1,-2,3,.5});const auto left=u::solveLeft(a,u::multiply(a,x)),right=u::solveRight(a,u::multiply(x,a));expect(left.solution&&near(*left.solution,x)&&right.solution&&near(*right.solution,x),"Left/right real-coordinate solves preserve operand placement.");expect(near(u::multiply(a,u::inverse(a)),u::Element::scalar(h,1)),"Quaternion inverse verifies a two-sided identity.");const auto dual=u::builtin("dual_quaternion");u::Element d(dual,{1,.2,-.1,.3,.2,1,2,3});expect(near(u::multiply(d,u::inverse(d)),u::Element::scalar(dual,1)),"Dual quaternion inverse respects ordered primal/dual products.");}
}
int main(){try{builtins();importer();solve();elementary();const auto real=u::builtin("real");const auto scaled=u::solveLeft(u::Element(real,{1e308}),u::Element(real,{1e-308}));expect(scaled.status==u::SolveStatus::NonFinite&&!scaled.solution,"Scaling cannot turn an unrepresentable nonzero solution into a successful zero solution.");const auto h=u::builtin("quaternion");const auto huge=u::Element(h,{1e308,1e308,0,0});expect(near(u::multiply(huge,u::inverse(huge)),u::Element::scalar(h,1)),"Canonical reciprocals retain huge finite arguments without overflowing their norm intermediates.");}catch(const std::exception& error){++failures;std::cerr<<error.what()<<'\n';}std::cout<<checks<<" universal algebra checks, "<<failures<<" failures\n";return failures?1:0;}
